def patch_text(rel: str, current: str, changes: list) -> str:
    result = current
    for i, ch in enumerate(changes,1):
        old, new = ch['old'], ch['new']
        count = result.count(old)
        if count != 1:
            raise ValueError(f'{rel} hunk {i}: expected unique anchor, found {count}. '
                             'Your source differs from the supplied V9 files. No V10 changes written.')
        result = result.replace(old,new,1)
    return result

def main() -> int:
    here=Path(__file__).resolve().parent
    roots=[Path(sys.argv[1]).resolve()] if len(sys.argv)>1 else [here,here/'web',Path.cwd(),Path.cwd()/'web']
    root=next((x for x in roots if (x/'src/game/fighter.ts').is_file()),None)
    if root is None:
        print('ERROR: Put this installer inside fight-royale/web or pass the web directory as the first argument.')
        return 2
    data=json.loads(zlib.decompress(base64.b85decode(DATA)))
    fighter=(root/'src/game/fighter.ts').read_text(encoding='utf-8')
    ui=(root/'src/ui/GameView.tsx').read_text(encoding='utf-8')
    # Bootstrap earlier V6/V7/V8 from the exact same bundled V9 installer used before.
    if ('NYTHERA_AERIAL_DREADFALL_V9' not in fighter or 'DreadfallTempoMeter' not in ui) and PATCH not in fighter:
        print('V9 not detected; applying earlier compatible patches first...')
        with tempfile.TemporaryDirectory(prefix='fr_v10_bootstrap_') as td:
            legacy=Path(td)/'install_nythera_v9.py'
            legacy.write_bytes(zlib.decompress(base64.b85decode(V9_INSTALLER)))
            r=subprocess.run([sys.executable,str(legacy),str(root)],check=False)
            if r.returncode:
                print('V9 prerequisite failed; V10 patch was not attempted.')
                return r.returncode
    pending=[]
    try:
        for rel,changes in data['patches'].items():
            path=root/rel
            if not path.is_file():raise FileNotFoundError(rel)
            before=path.read_text(encoding='utf-8')
            if PATCH in before or ('// V10: all passives' in before and rel.endswith('GameView.tsx')):
                print('ALREADY UPDATED:',rel)
                continue
            after=patch_text(rel,before,changes)
            if after!=before:pending.append((path,before.encode('utf-8'),after.encode('utf-8')))
        csspath=root/'src/app/globals.css'
        if not csspath.is_file():raise FileNotFoundError('src/app/globals.css')
        css=csspath.read_text(encoding='utf-8')
        if PATCH not in css:
            pending.append((csspath,css.encode('utf-8'),(css.rstrip()+'\n\n'+data['css']+'\n').encode('utf-8')))
        # Do not overwrite existing handmade passive artwork. Add only missing icons.
        for name,encoded in data['icons'].items():
            target=root/'public/icons/passives'/name
            if not target.is_file():pending.append((target,None,base64.b85decode(encoded)))
    except Exception as exc:
        print('VALIDATION ERROR:',exc)
        return 3
    if not pending:
        print('Fight Royale V10 already installed. Nothing changed.')
        return 0
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    prepared=[]; written=[]
    try:
        # Stage all temporary outputs and backups before any original is changed.
        for path,before,after in pending:
            path.parent.mkdir(parents=True,exist_ok=True)
            backup=path.with_name(path.name+'.before_'+PATCH+'_'+stamp+'.bak') if before is not None else None
            if backup is not None:backup.write_bytes(before)
            tmp=path.with_name(path.name+'.'+PATCH+'.tmp')
            tmp.write_bytes(after)
            prepared.append((path,backup,tmp))
        for path,backup,tmp in prepared:
            tmp.replace(path)
            written.append((path,backup))
            print('UPDATED:',path.relative_to(root))
    except BaseException as exc:
        print('WRITE ERROR:',exc,'Rolling back V10 writes...')
        for path,backup in reversed(written):
            if backup and backup.is_file():shutil.copy2(backup,path)
            elif path.is_file():path.unlink()
        for path,backup,tmp in prepared:
            if tmp.is_file():tmp.unlink()
        return 4
    print('\nSUCCESS — Fight Royale V10: 20 hero passives + live black counters + spectator skills.')
    print('Nythera CPU attacks and flanks; Aster/Vesper stacks persist across rounds.')
    print('Run: npx tsc --noEmit -p .  then  npm run dev')
    return 0

if __name__=='__main__':
    sys.exit(main())
